   "fetched": "2026-10-22",
   "note": "鲁迅（1881-1936）原名周树人，浙江绍兴人。文学家、思想家、教育家。1920年起在高师国文部任教。1923年起在女高师国文系任教。讲授中国小说史等课。师大和女师大是鲁迅最早任教和任教时间最长的两所学校。",
