   "note": "吴承仕（1884-1939），别号检斋，安徽歙县人。清末最后之举人，亦为“章门弟子”之一，精“三礼名物”，为“经学之王”。他较早接受马列主义、辨证唯物论，并自觉运用到学术研究中去，为早期著名学者中的中共党员。自改大立系后他是第一任国文系主任，利用其声名和影响力，聘请“章门弟子”、著名的“训诂之王”黄侃（季刚）及鲁迅、范文澜、马叙伦、杨树达等众多的“名家”来系任教或讲演，使学生无论在学业还是思想上都",
