   "note": "钱玄同（1887-1939），又名夏，号疑古，浙江吴兴人。语言文字学家、教育家、新文化运动的闯将。“章（太炎）门弟子”之一，精音韵，为“音韵之王”。力主改革汉字、废除文言，其在“五四”前后，办《新青年》反复古派（和刘半农合演“双簧”《答王敬轩》，十分有名），鼓动鲁迅“呐喊”（鲁迅《呐喊·自序》中所说“金心异”即钱玄同），提出打倒“桐城谬种，选学妖孽”的口号等。对推行白话文、改革汉字、改革汉字书写、",
