   "note": "沈兼士（1887-1947），名臤，吴兴（今湖州）人。沈尹默之弟。中国语言文字学家、文献档案学家。1987年7月31日出生于陕西省汉阴县城，1905年19岁时与兄沈尹默自费东渡日本求学，入东京物理学校。时章太炎先生居东瀛，沈兼士拜其门下，并加入同盟会。归国之后，先后任教于北平大学（今北京大学）、辅仁大学（今北京师范大学）、清华大学、厦门大学等多所高校。1922年在北京大学创办研究所国学门，任主任。",
