   "note": "刘半农（1891-1934），原名寿彭，改名复，字半侬，后改字半农，晚号曲庵，笔名寒星、范奴冬女士。堂号有灵霞馆、桐花芝豆堂等。江苏省江阴县人。他是语音学专家，又是文学家和教育家。1917年夏应蔡元培之邀，出任北京大学预科国文教授。1920年携家属去英国伦敦大学攻读语言，后又入法国巴黎大学学习。1925年8月回国，继续担任北京大学国文系教授，1930年任北平大学女子文理学院（今北京师范大学文学院）",
