   "note": "钟敬文(1903-2002)，广东海丰人，1930年与友人合创中国民俗学会。1934年春，赴日本留学，在东京早稻田大学研究院从事神话学、民俗学的研究，1936年回国。1949年，被选为中国文学艺术界联合会第一次代表大会候补委员及文学工作者联合会（后改为作家协会）党委委员。同年9月受聘为北京师范大学中文系教授直至辞世。生前曾任中国民间文艺家协会名誉主席、中国民俗学会理事长及中国文学艺术界联合会荣誉委",
