   "note": "顾随（1897-1960），本名顾宝随，字羡季，又自号苦水，河北省清河县人。一九二零年先生自北大英文系毕业后，即投身于教育工作。其初在河北及山东各地之中学担任英语及国文等课，未几，应聘赴天津，在河北女师学院任教。其后又转赴北京，曾先后在燕京大学及辅仁大学任教，并曾在北京师范大学、北平大学、女子文理学院、中法大学及中国大学等校兼课。解放后一度担任辅仁大学（今北京师范大学）中文系系主任。",
