   "note": "谭丕模（1900-1958），湖南省祁阳县人，文学史家。1925年在衡阳船山中学毕业后考入北京师范大学，热心参加反帝爱国运动。中华人民共和国成立后，担任湖南大学国文系主任、中南军政委员会委员，还当选为湖南省和长沙市的人大代表、政协委员、文联主席及中南文联、作协的常务理事。1953年回母校北京师大任中国文学教研室主任、北师大党委委员。",
