   "note": "沈从文（1902-1988），现代作家、历史文物研究家。原名沈岳焕，笔名小兵、懋琳、休芸芸等。湖南凤凰（今属湘西土家族苗族自治州）人。苗族。1918年小学毕业后随本乡土著部队到沅水流域各地，随军在川、湘、鄂、黔四省边区生活，开始接触中外文学作品。1923年到北京自学并学习写作。曾去北京大学旁听。1924年后开始发表作品。1930年起在武汉大学、青岛大学任教。抗日战争爆发后，到昆明任西南联合大学教授",
