   "note": "李何林（1904-1988），曾用名李延寿、李振发、李昨非、李竹年等。生于安徽霍邱县。上个世纪40年代，他一度在云南、台湾等省大学中文系任教并业余从事革命文艺运动，后到过解放区，曾担任华北大学国文系主任，华北人民代表会议代表。1949年3月随校进入北平。7月参加全国文艺界第一次代表大会，当选为全国文艺界协会候补理事。后调任北京师范大学中文系任教。参与制定《中国新文学教学大纲》，为中国现代文学学科的",
