   "note": "陆宗达（1905-1988），著名语言文字学家、业余昆曲家。字颖明、又作颖民，浙江慈溪人，生长在北京。1922年考入北京大学国文系预科，后升入本科。1926年起又师从国学大师黄侃（季刚），以《说文解字》为中心，治汉语文字音韵训诂之学，精研典籍。1931年起因在传统语言学研究中建树甚多，先后被北京大学、民国大学、中国大学、北平女子文理学院和辅仁大学等聘为讲师和教授，并兼任国学研究所编辑。抗日战争期间",
