   "note": "李长之(1910-1978)，原名李长治、李长植，山东利津人。1929年入北京大学预科学习，在校期间发表散文作品。1936年出版《鲁迅批判》—书，产生影响。该年自清华大学毕业，遂留校任教。以后又历任京华美术学院、云南大学、重庆中央大学的教职。1940年任教育部研究员。1944年主编《时与潮》副刊。1945年任国立编译馆编审。抗战胜利随编译馆由重庆北碚迁南京，主编《和平日报》副刊。1946年10月赴",
