   "note": "叶丁易(1913-1954)，原名叶鼎彝，又名孙恬。安徽桐城人。1938年毕业于北平师范大学。曾任西北师范学院讲师，国立戏剧专科学校、四川大学、东北大学副教授，《民主报》总编辑。1944年加入中国民主同盟。1947年加入九三学社。1949年出席中国人民政治协商会议第一届全体会议。建国后，历任北京师范大学教授，九三学社第二届中央理事、第三届中央常委。1953年赴莫斯科大学讲学。次年病逝于莫斯科。著有",
