   "note": "俞敏（1916-1995），生于天津。当代著名的语言学家、教育家。一九四〇年毕业于辅仁大学中文系，一九四六年暑期赴台北任台湾国语推行委员会委员，一九四七年至一九五二年先后在燕京大学、北京大学执教，一九五三年直至辞世任北京师范大学中文系教授，曾任中国语言学会常务理事、中国音韵学会顾问、国际交流学会理事、北京语言学会顾问、国务院学位委员会第二届学科评议组（中国语言文学分组）成员、中国大百科全书语言文学",
